  const editProduct=(p:Product)=>setEditing({...p})
  const newProduct=()=>setEditing({id:`p-${Date.now()}`,slug:'new-piece',name:'New piece',category:categories[0]||'Men',type:'Essentials',price:0,stock:0,image:'',image2:'',images:[],colors:['#d9d4cb'],sizes:['S','M','L'],description:''})
  const uploadProductImages=async(files:FileList|null)=>{if(!editing||!files?.length)return;const selected=Array.from(files);const valid=selected.filter(file=>['image/jpeg','image/png','image/webp','image/avif'].includes(file.type)&&file.size<=8*1024*1024);if(valid.length!==selected.length){flash('Some files were skipped. Use JPG, PNG, WEBP, or AVIF images up to 8 MB each.')}if(!valid.length)return;setImageUploading(true);try{const {supabase}=await import('./supabase');const uploaded=await Promise.all(valid.map(async file=>{const extension=file.type.split('/')[1].replace('jpeg','jpg');const path=`products/${Date.now()}-${crypto.randomUUID()}.${extension}`;const {data,error}=await supabase.storage.from('store-images').upload(path,file,{cacheControl:'3600',contentType:file.type,upsert:false});if(error)throw error;return supabase.storage.from('store-images').getPublicUrl(data.path).data.publicUrl}));setEditing(current=>{if(!current)return current;const images=[...productImages(current),...uploaded];return {...current,images,image:images[0],image2:images[1]||''}});flash(`${uploaded.length} image${uploaded.length===1?'':'s'} uploaded. Save the product to publish.`)}catch(error){flash(error instanceof Error?error.message:'Could not upload the selected images.')}finally{setImageUploading(false)}}
