  const persistProduct=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!editing)return;if(!productImages(editing).length){flash('Add at least one product image before saving.');return}const value={...editing,slug:editing.name.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/,''),price:Number(editing.price),stock:Math.max(0,Number(editing.stock)||0)};const exists=catalog.some(p=>p.id===value.id);try{await saveCatalog(exists?catalog.map(p=>p.id===value.id?value:p):[value,...catalog]);setEditing(null);flash('Product saved.')}catch(error){flash(error instanceof Error?error.message:'Could not save product.')}}
  const persistProduct=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!editing||productSaving)return;if(!productImages(editing).length){flash('Add at least one product image before saving.');return}const baseSlug=editing.name.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/,'')||'piece';const exists=catalog.some(p=>p.id===editing.id);setProductSaving(true);try{const {supabase}=await import('./supabase');const {data:storedProducts,error:readError}=await supabase.from('products').select('id,slug');if(readError)throw readError;const slugTaken=[...catalog,...(storedProducts||[])].some(product=>product.id!==editing.id&&product.slug===baseSlug);const value={...editing,slug:slugTaken?`${baseSlug}-${editing.id.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}`:baseSlug,price:Number(editing.price),stock:Math.max(0,Number(editing.stock)||0)};await saveCatalog(exists?catalog.map(p=>p.id===value.id?value:p):[value,...catalog]);setEditing(null);flash('Product saved.')}catch(error){const message=error instanceof Error?error.message:'Could not save product.';flash(/products_slug_key|duplicate key/i.test(message)?'A product already uses this URL name. Change the product name and try again.':message)}finally{setProductSaving(false)}}
